package fraymus.workspace;

import org.json.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Prospective contact experiments and pooled uncertainty. No controller writes. */
final class ContactStudy064 {
    static final String PROTOCOL="contact-pooled-uncertainty-064-v1";
    static final List<String> VARIANTS=List.of("baseline","zeroClearance","halfStep","rotationLocked");
    static final List<String> METHODS=List.of("pooled","fixed20mm");
    static final int TOTAL=170;
    private static final class Identity {static final String VALUE=implementation();}
    static String source(){return Identity.VALUE;}
    private static String implementation(){var b=new StringBuilder(PROTOCOL).append(Stopping063.source());var queue=new ArrayDeque<Class<?>>();queue.addAll(List.of(ContactStudy064.class,ContactRamp064.class,ContactMath064.class));while(!queue.isEmpty()){var c=queue.remove();try(var in=c.getResourceAsStream(c.getName().substring(c.getPackageName().length()+1)+".class")){b.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}Arrays.stream(c.getDeclaredClasses()).sorted(Comparator.comparing(Class::getName)).forEach(queue::add);}return MeasurementStore.hash(b.toString());}
    static JSONArray anchors(){var out=new JSONArray();for(double a:new double[]{24,29})for(double v:new double[]{.18,.33})out.put(Stopping063.definition(a,1.05,v));return out;}
    static JSONArray cases(String phase){
        int seed=switch(phase){case "calibration"->64001;case "reserved"->64002;case "stress"->64003;default->throw new IllegalArgumentException("Unknown contact partition");};boolean stress=phase.equals("stress");var random=new Random(seed);var out=new JSONArray();
        for(int group=0;group<2;group++)for(int i=0;i<(stress?15:30);i++){double a=(stress?8:12)+(stress?4:20)*random.nextDouble(),v=.05+.35*random.nextDouble(),u=random.nextDouble(),ratio=stress?(group==0?.70+.15*u:1.20+.10*u):(group==0?.85+.14*u:1.01+.19*u);out.put(Stopping063.definition(a,ratio,v));}return out;
    }
    static JSONObject manifest(){return new JSONObject().put("protocol",PROTOCOL).put("source",source()).put("anchors",anchors()).put("variants",new JSONArray(VARIANTS)).put("calibration",cases("calibration")).put("reserved",cases("reserved")).put("stress",cases("stress")).put("proposed","pooled").put("nominalCoverage",.9).put("minimumCoverage",.9).put("minimumRegimeCoverage",.85).put("maximumMeanWidthM",.08).put("controllerAuthority",false).put("totalNativeRuns",TOTAL);}
    static JSONObject trial(JSONObject c,String variant,Path dir,Runnable cancel)throws Exception{
        try(var world=new ContactRamp064(c,variant,dir)){var settings=world.settings();int ticks=variant.equals("halfStep")?1440:720;var samples=new JSONArray().put(world.sample());for(int t=1;t<=ticks;t++){cancel.run();world.step();samples.put(world.sample());}
            var r=new JSONObject().put("id",UUID.randomUUID().toString()).put("definition",c).put("variant",variant).put("ticks",ticks).put("source",source()).put("physicalParameters",RampDefinition.from(ResidualOutcome062.physical(c)).json()).put("settings",settings).put("observedAt",Instant.now().toString()).put("samples",samples);r.put("summary",ContactMath064.summary(r));r.put("sha256",WorldFrames.hash(r));verify(r);return r;
        }
    }
    static void verify(JSONObject r){
        var copy=WorldFrames.copy(r);copy.remove("sha256");if(!source().equals(r.getString("source"))||!WorldFrames.hash(copy).equals(r.getString("sha256")))throw new IllegalStateException("Contact record/source differs");UUID.fromString(r.getString("id"));Instant.parse(r.getString("observedAt"));
        String variant=r.getString("variant");if(!VARIANTS.contains(variant))throw new IllegalStateException("Unsupported contact variant");double dt=variant.equals("halfStep")?1.0/480:BulletRamp.DT;int ticks=variant.equals("halfStep")?1440:720;var settings=r.getJSONObject("settings");
        if(settings.getDouble("dt")!=dt||settings.getDouble("initialClearanceM")!=(variant.equals("zeroClearance")?0:.001)||settings.getInt("iterations")!=10||!settings.getString("backend").equals(BulletRamp.BACKEND)||!settings.getString("solver").equals("SI")||!settings.getJSONArray("angularFactor").similar(new JSONArray(variant.equals("rotationLocked")?new int[]{0,0,0}:new int[]{1,1,1})))throw new IllegalStateException("Native contact settings differ");
        settings.getInt("mode");settings.getBoolean("splitImpulse");if(!RampDefinition.from(ResidualOutcome062.physical(r.getJSONObject("definition"))).json().similar(r.getJSONObject("physicalParameters")))throw new IllegalStateException("Contact physical parameters differ");
        var samples=r.getJSONArray("samples");if(r.getInt("ticks")!=ticks||samples.length()!=ticks+1)throw new IllegalStateException("Incomplete contact clock");for(int i=0;i<=ticks;i++){var s=samples.getJSONObject(i);if(s.getInt("tick")!=i||Math.abs(s.getDouble("timeS")-i*dt)>1e-12)throw new IllegalStateException("Contact clock differs");}
        if(!ContactMath064.summary(r).similar(r.getJSONObject("summary")))throw new IllegalStateException("Contact summary differs");
    }
    static double calibrate(JSONArray rows){if(rows.length()!=60)throw new IllegalStateException("Need 60 calibration records");double[] errors=new double[60];for(int i=0;i<60;i++){var row=rows.getJSONObject(i);if(!cases("calibration").getJSONObject(i).similar(row.getJSONObject("definition")))throw new IllegalStateException("Calibration cases differ");Stopping063.verify(row.getJSONObject("record"));errors[i]=Math.abs(row.getJSONObject("record").getJSONObject("summary").getDouble("endpointErrorM"));}return Stopping063.quantile(errors);}
    static JSONObject intervals(double radius,JSONObject c,boolean stress){if(stress)ResidualOutcome062.physical(c);else Stopping063.queryDomain(c);if(!Double.isFinite(radius)||radius<0)throw new IllegalArgumentException("Invalid interval radius");double mean=Stopping063.analytic(c,.75);var out=new JSONObject();for(String method:METHODS){double half=method.equals("pooled")?radius:.02;out.put(method,new JSONObject().put("predictionM",mean).put("radiusM",half).put("lowerM",mean-half).put("upperM",mean+half));}return out;}
    static JSONObject evaluate(JSONArray rows,boolean stress){
        int count=stress?30:60;if(rows.length()!=count)throw new IllegalStateException("Incomplete uncertainty evaluation");var methods=new JSONObject();
        for(String method:METHODS){int total=0;int[] counts=new int[2],hits=new int[2];double widths=0;var misses=new JSONArray();for(int i=0;i<count;i++){var row=rows.getJSONObject(i);int g=Stopping063.regime(row.getJSONObject("definition")).equals("accelerating")?0:1;var v=row.getJSONObject("intervalsBeforeObservation").getJSONObject(method);double actual=row.getJSONObject("record").getJSONObject("summary").getDouble("endpointM"),width=v.getDouble("upperM")-v.getDouble("lowerM");if(!Double.isFinite(width)||width<0)throw new IllegalStateException("Invalid interval width");widths+=width;counts[g]++;if(actual>=v.getDouble("lowerM")&&actual<=v.getDouble("upperM")){hits[g]++;total++;}else misses.put(i+1);}
            var groups=new JSONObject();for(int g=0;g<2;g++){if(counts[g]!=count/2)throw new IllegalStateException("Unbalanced evaluation regimes");groups.put(g==0?"accelerating":"slowing",new JSONObject().put("hits",hits[g]).put("count",counts[g]).put("coverage",hits[g]/(double)counts[g]).put("wilson95",ContactMath064.wilson(hits[g],counts[g])));}
            methods.put(method,new JSONObject().put("covered",total).put("count",count).put("coverage",total/(double)count).put("regimes",groups).put("meanWidthM",widths/count).put("missedCases",misses).put("wilson95",ContactMath064.wilson(total,count)));
        }
        var p=methods.getJSONObject("pooled");boolean qualified=!stress&&p.getDouble("coverage")>=.9&&p.getJSONObject("regimes").getJSONObject("accelerating").getDouble("coverage")>=.85&&p.getJSONObject("regimes").getJSONObject("slowing").getDouble("coverage")>=.85&&p.getDouble("meanWidthM")<=.08;
        return new JSONObject().put("methods",methods).put("proposed","pooled").put("qualified",qualified).put("stress",stress).put("controllerAuthority",false).put("interpretation",stress?"Deliberate out-of-domain stress; no calibrated coverage claim":"Reserved simulation evaluation; descriptive sampling intervals, no physical guarantee");
    }
    static void run(JSONObject job,Path dir,Runnable cancel,FraynixOutcome061.Progress progress)throws Exception{
        job.put("manifest064",manifest()).put("diagnostics064",new JSONArray()).put("calibration064",new JSONArray()).put("reserved064",new JSONArray()).put("stress064",new JSONArray()).put("progress",0).put("total",TOTAL);progress.save("Contact study declared");
        for(Object raw:anchors())for(String variant:VARIANTS){cancel.run();var c=(JSONObject)raw;var row=new JSONObject().put("definition",c).put("variant",variant).put("predictedAt",Instant.now().toString());job.getJSONArray("diagnostics064").put(row);progress.save("Recording "+variant+" manifold evidence");row.put("record",trial(c,variant,dir,cancel));job.put("progress",job.getInt("progress")+1);
            if(variant.equals("baseline")){var old=Stopping063.trial(c,"baseline",720,1,dir,cancel);row.put("original063",old);var a=old.getJSONObject("summary");var b=row.getJSONObject("record").getJSONObject("summary");double delta=Math.max(Math.abs(a.getDouble("endpointM")-b.getDouble("endpointM")),Math.abs(a.getDouble("finalDistanceM")-b.getDouble("finalDistanceM")));row.put("parityErrorM",delta);if(delta>1e-6)throw new IllegalStateException("Persistent reads changed original native motion");job.put("progress",job.getInt("progress")+1);}progress.save("Contact intervention retained");
        }
        for(String phase:List.of("calibration","reserved","stress")){
            if(phase.equals("reserved")){var model=new JSONObject().put("radiusM",calibrate(job.getJSONArray("calibration064"))).put("calibrationSha256",WorldFrames.hash(new JSONObject().put("rows",job.getJSONArray("calibration064")))).put("pinnedAt",Instant.now().toString());job.put("intervalModel064",model).put("intervalModelSha256064",WorldFrames.hash(model));progress.save("Pooled radius frozen before new observations");}
            for(Object raw:cases(phase)){cancel.run();var c=(JSONObject)raw;var row=new JSONObject().put("definition",c).put("predictedAt",Instant.now().toString());if(!phase.equals("calibration"))row.put("intervalsBeforeObservation",intervals(job.getJSONObject("intervalModel064").getDouble("radiusM"),c,phase.equals("stress")));job.getJSONArray(phase+"064").put(row);progress.save(phase+" prediction saved before observation");row.put("record",Stopping063.trial(c,"baseline",180,4,dir,cancel));job.put("progress",job.getInt("progress")+1);progress.save(phase+" native observation retained");}
        }
        var evaluation=evaluate(job.getJSONArray("reserved064"),false);job.put("evaluation064",evaluation).put("stressEvaluation064",evaluate(job.getJSONArray("stress064"),true)).put("accepted",evaluation.getBoolean("qualified")).put("reason",evaluation.getBoolean("qualified")?"Pooled interval passed declared reserved gate; advisory only":"Pooled interval failed declared reserved gate; evidence retained");audit(job);progress.save("Contact and uncertainty checks complete");
    }
    static void audit(JSONObject job){
        if(!manifest().similar(job.getJSONObject("manifest064")))throw new IllegalStateException("Contact manifest differs");var seen=new HashSet<String>();var rows=job.getJSONArray("diagnostics064");if(rows.length()!=16)throw new IllegalStateException("Incomplete interventions");
        for(int i=0;i<16;i++){var row=rows.getJSONObject(i);var r=row.getJSONObject("record");verify(r);checkRow(row,r,anchors().getJSONObject(i/4),seen);if(!row.getString("variant").equals(VARIANTS.get(i%4))||!r.getString("variant").equals(VARIANTS.get(i%4)))throw new IllegalStateException("Intervention differs");
            if(i%4==0){var old=row.getJSONObject("original063");Stopping063.verify(old);if(!seen.add(old.getString("id"))||!old.getJSONObject("definition").similar(row.getJSONObject("definition"))||!old.getString("variant").equals("baseline")||old.getInt("ticks")!=720||old.getInt("stride")!=1)throw new IllegalStateException("Original parity identity differs");var a=old.getJSONObject("summary");var b=r.getJSONObject("summary");double delta=Math.max(Math.abs(a.getDouble("endpointM")-b.getDouble("endpointM")),Math.abs(a.getDouble("finalDistanceM")-b.getDouble("finalDistanceM")));if(delta>1e-6||row.getDouble("parityErrorM")!=delta)throw new IllegalStateException("Original parity differs");}
        }
        var model=job.getJSONObject("intervalModel064");if(!WorldFrames.hash(model).equals(job.getString("intervalModelSha256064"))||model.getDouble("radiusM")!=calibrate(job.getJSONArray("calibration064"))||!WorldFrames.hash(new JSONObject().put("rows",job.getJSONArray("calibration064"))).equals(model.getString("calibrationSha256")))throw new IllegalStateException("Pooled calibration differs");Instant pinned=Instant.parse(model.getString("pinnedAt"));
        for(String phase:List.of("calibration","reserved","stress")){var cases=cases(phase);var actual=job.getJSONArray(phase+"064");if(cases.length()!=actual.length())throw new IllegalStateException("Partition incomplete");for(int i=0;i<cases.length();i++){var row=actual.getJSONObject(i);var r=row.getJSONObject("record");Stopping063.verify(r);checkRow(row,r,cases.getJSONObject(i),seen);if(r.getInt("ticks")!=180||r.getInt("stride")!=4||!r.getString("variant").equals("baseline"))throw new IllegalStateException("Uncertainty native clock differs");if(phase.equals("calibration")){if(Instant.parse(r.getString("observedAt")).isAfter(pinned))throw new IllegalStateException("Calibration after freeze");}else if(Instant.parse(row.getString("predictedAt")).isBefore(pinned)||!intervals(model.getDouble("radiusM"),cases.getJSONObject(i),phase.equals("stress")).similar(row.getJSONObject("intervalsBeforeObservation")))throw new IllegalStateException("Intervals or chronology differ");}}
        if(!evaluate(job.getJSONArray("reserved064"),false).similar(job.getJSONObject("evaluation064"))||!evaluate(job.getJSONArray("stress064"),true).similar(job.getJSONObject("stressEvaluation064")))throw new IllegalStateException("Evaluation differs");
    }
    private static void checkRow(JSONObject row,JSONObject r,JSONObject c,Set<String> seen){if(!seen.add(r.getString("id"))||!c.similar(row.getJSONObject("definition"))||!c.similar(r.getJSONObject("definition"))||Instant.parse(row.getString("predictedAt")).isAfter(Instant.parse(r.getString("observedAt"))))throw new IllegalStateException("Record identity or chronology differs");}
}
